resource gatewaySubnet 'Microsoft.Network/virtualNetworks/subnets@2023-11-01' = {
  parent: vnet
  name: 'GatewaySubnet'                 // must be exactly this name
  properties: { addressPrefix: '10.0.255.0/27' }
}

resource vpnGateway 'Microsoft.Network/virtualNetworkGateways@2023-11-01' = {
  name: 'vgw-quotient'
  location: location
  properties: {
    gatewayType: 'Vpn'
    vpnType: 'RouteBased'
    enableBgp: true
    activeActive: true                   // two tunnels: no single point of failure
    sku: { name: 'VpnGw2AZ', tier: 'VpnGw2AZ' }
    ipConfigurations: [
      { name: 'active1', properties: { publicIPAddress: { id: pip1.id }, subnet: { id: gatewaySubnet.id } } }
      { name: 'active2', properties: { publicIPAddress: { id: pip2.id }, subnet: { id: gatewaySubnet.id } } }
    ]
  }
}

resource connection 'Microsoft.Network/connections@2023-11-01' = {
  name: 'cn-onprem'
  location: location
  properties: {
    connectionType: 'IPsec'
    connectionProtocol: 'IKEv2'
    virtualNetworkGateway1: { id: vpnGateway.id }
    localNetworkGateway2: { id: localGateway.id }
    sharedKey: vpnSharedKey
    enableBgp: true
    routingWeight: 0
  }
}
